sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float count;
uniform float height;
uniform float angle;
uniform float thickness;
uniform float phase;
uniform float invert;
layout(color) uniform half4 edgeColor;
layout(color) uniform half4 color1;
layout(color) uniform half4 color2;
layout(color) uniform half4 light;
uniform float lightAngle;
uniform float map;
uniform float mask;
float heightAt(float2 p) {
    half4 c = image.eval(p);
    float h = map > 0.5 ? (c.a > 0.0 ? dot(float3(c.rgb) / float(c.a), float3(0.2126, 0.7152, 0.0722)) * float(c.a) : 0.0) : float(c.a);
    return invert > 0.5 ? 1.0 - h : h;
}
half4 main(float2 coord) {
    float ra = radians(angle);
    float2 ax = float2(cos(ra), sin(ra));
    float2 ay = float2(-ax.y, ax.x);
    float2 mid = size * 0.5;
    float2 r = float2(dot(coord - mid, ax), dot(coord - mid, ay));
    float extent = abs(dot(size, abs(ay)));
    float gap = extent / max(count, 0.5);
    float tall = max(height, 0.0) * gap;
    float thick = clamp(thickness, 0.0, 1.0) * gap * 0.5;
    float first = floor((r.y + tall + thick) / gap - phase);
    for (int k = 0; k < 48; k++) {
        float i = first - float(k);
        float base = (i + phase) * gap;
        if (base < r.y) break;
        float2 at = mid + r.x * ax + base * ay;
        float h = heightAt(at) * tall;
        float top = base - h;
        if (r.y >= top - thick) {
            float3 rgb;
            if (r.y < top) {
                float slope = (heightAt(at + ax * 2.0) - heightAt(at - ax * 2.0)) * tall / 4.0;
                float la = radians(lightAngle);
                float lit = 0.5 + 0.5 * dot(normalize(float2(slope, -1.0)), float2(cos(la), -sin(la)));
                rgb = float3(edgeColor.rgb) * float3(light.rgb) * mix(0.35, 1.0, lit);
            } else {
                float t = h > 0.0 ? clamp((r.y - top) / h, 0.0, 1.0) : 1.0;
                rgb = mix(float3(color1.rgb), float3(color2.rgb), t);
            }
            float a = mask > 0.5 ? float(image.eval(coord).a) : 1.0;
            return half4(half3(rgb * a), half(a));
        }
    }
    return half4(0.0);
}
